	@Test
	void cancellationRemainsAttachedWhileTheViewPrefetchesALazyFirstItem() throws Exception {
		RepositoryResolver resolver = mock(RepositoryResolver.class);
		org.eclipse.rdf4j.repository.Repository repository = mock(org.eclipse.rdf4j.repository.Repository.class);
		RepositoryConnection connection = mock(RepositoryConnection.class);
		TupleQuery query = mock(TupleQuery.class);
		TupleQueryResult result = mock(TupleQueryResult.class);
		CountDownLatch lazyHasNext = new CountDownLatch(1);
		CountDownLatch interrupted = new CountDownLatch(1);
		MockHttpServletRequest request = newQueryRequest();
		request.setParameter(Protocol.QUERY_REQUEST_ID_PARAM_NAME, "lazy-query");
		MockHttpServletResponse response = new MockHttpServletResponse();
		when(resolver.getRepository(request)).thenReturn(repository);
		when(resolver.getRepositoryID(org.mockito.ArgumentMatchers.any(HttpServletRequest.class)))
				.thenReturn("repository");
		when(resolver.getRepositoryConnection(request, repository)).thenReturn(connection);
		when(connection.prepareQuery(QueryLanguage.SPARQL, QUERY, null)).thenReturn(query);
		when(query.evaluate()).thenReturn(result);
		when(result.getBindingNames()).thenReturn(List.of());
		when(result.hasNext()).thenAnswer(invocation -> {
			lazyHasNext.countDown();
			try {
				new CountDownLatch(1).await();
				return false;
			} catch (InterruptedException e) {
				interrupted.countDown();
				throw new org.eclipse.rdf4j.query.QueryInterruptedException("cancelled", e);
			}
		});

		DefaultQueryRequestHandler handler = new DefaultQueryRequestHandler(resolver);
		ModelAndView modelAndView = handler.handleQueryRequest(request, RequestMethod.POST, response);
		assertThat(modelAndView).isNotNull();

		ExecutorService executor = Executors.newSingleThreadExecutor();
		try {
			Future<?> render = executor.submit(() -> {
				try {
					((org.springframework.web.servlet.View) modelAndView.getView()).render(modelAndView.getModel(),
							request,
							response);
				} catch (Exception e) {
					throw new AssertionError(e);
				}
			});
			assertThat(lazyHasNext.await(5, TimeUnit.SECONDS)).isTrue();

			MockHttpServletRequest cancel = new MockHttpServletRequest();
			cancel.setMethod(RequestMethod.POST.name());
			cancel.setParameter(Protocol.CANCEL_QUERY_PARAM_NAME, "true");
			cancel.setParameter(Protocol.QUERY_REQUEST_ID_PARAM_NAME, "lazy-query");
			MockHttpServletResponse cancelResponse = new MockHttpServletResponse();
			assertThat(handler.handleCancelQuery(cancel, cancelResponse)).isTrue();
			assertThat(cancelResponse.getStatus()).isEqualTo(MockHttpServletResponse.SC_NO_CONTENT);
			assertThat(interrupted.await(5, TimeUnit.SECONDS)).isTrue();
			render.get(5, TimeUnit.SECONDS);
			verify(result).close();
		} finally {
			executor.shutdownNow();
			handler.shutdown();
		}
	}

