	@Test
	void realSocketDisconnectCancelsANormalRequestWithoutASuppliedRequestId() throws Exception {
		RepositoryResolver resolver = mock(RepositoryResolver.class);
		HTTPRepository repository = mock(HTTPRepository.class);
		RepositoryConnection connection = mock(RepositoryConnection.class);
		TupleQuery query = mock(TupleQuery.class);
		CountDownLatch evaluationStarted = new CountDownLatch(1);
		CountDownLatch evaluationInterrupted = new CountDownLatch(1);
		CountDownLatch requestFinished = new CountDownLatch(1);
		AtomicReference<String> generatedRequestId = new AtomicReference<>();
		AtomicReference<Throwable> requestFailure = new AtomicReference<>();

		when(resolver.getRepositoryID(org.mockito.ArgumentMatchers.any(HttpServletRequest.class)))
				.thenReturn("repository");
		when(connection.prepareQuery(QueryLanguage.SPARQL, QUERY, null)).thenReturn(query);
		when(query.evaluate()).thenAnswer(invocation -> {
			generatedRequestId.set(QueryRequestContext.getQueryRequestId());
			evaluationStarted.countDown();
			try {
				new CountDownLatch(1).await();
				return mock(TupleQueryResult.class);
			} catch (InterruptedException e) {
				evaluationInterrupted.countDown();
				throw new org.eclipse.rdf4j.query.QueryInterruptedException("client disconnected", e);
			}
		});

		DefaultQueryRequestHandler handler = new DefaultQueryRequestHandler(resolver);
		ExecutorService httpExecutor = Executors.newCachedThreadPool();
		HttpServer server;
		try {
			server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
		} catch (IOException e) {
			Assumptions.assumeTrue(false, "Loopback HTTP server unavailable: " + e.getMessage());
			return;
		}
		server.setExecutor(httpExecutor);
		server.createContext("/query", exchange -> {
			MockHttpServletRequest request = newQueryRequest();
			request.setRequestURI("/query");
			ExchangeResponse response = new ExchangeResponse(exchange);
			when(resolver.getRepository(request)).thenReturn(repository);
			when(resolver.getRepositoryConnection(request, repository)).thenReturn(connection);
			try {
				ModelAndView modelAndView = handler.handleQueryRequest(request, RequestMethod.POST, response);
				if (modelAndView != null) {
					modelAndView.getView().render(modelAndView.getModel(), request, response);
				}
			} catch (Throwable t) {
				requestFailure.set(t);
			} finally {
				try {
					exchange.close();
				} finally {
					requestFinished.countDown();
				}
			}
		});
		server.start();
		try {
			try (Socket socket = new Socket("127.0.0.1", server.getAddress().getPort())) {
				socket.setSoTimeout(15_000);
				OutputStream request = socket.getOutputStream();
				request.write(("POST /query HTTP/1.1\r\nHost: localhost\r\nContent-Length: 0\r\n\r\n")
						.getBytes(java.nio.charset.StandardCharsets.US_ASCII));
				request.flush();
				assertThat(readHttpHeaders(socket.getInputStream())).contains("HTTP/1.1 200");
				assertThat(evaluationStarted.await(5, TimeUnit.SECONDS)).isTrue();
			}

			assertThat(evaluationInterrupted.await(15, TimeUnit.SECONDS)).isTrue();
			assertThat(requestFinished.await(15, TimeUnit.SECONDS)).isTrue();
			assertThat(generatedRequestId).isNotNull();
			assertThat(generatedRequestId.get()).isNotBlank();
			verify(repository, org.mockito.Mockito.timeout(10_000)).cancelQuery(generatedRequestId.get());
			verify(connection, org.mockito.Mockito.atLeastOnce()).close();
			assertThat(requestFailure.get()).isNull();
		} finally {
			server.stop(0);
			httpExecutor.shutdownNow();
			handler.shutdown();
		}
	}

	private static ModelAndView runQuery(DefaultQueryRequestHandler handler, MockHttpServletRequest request,
			DisconnectingResponse response, CountDownLatch evaluationStarted, CountDownLatch evaluationInterrupted)
			throws Exception {
		var executor = java.util.concurrent.Executors.newSingleThreadExecutor();
		try {
			var future = executor.submit(() -> handler.handleQueryRequest(request, RequestMethod.POST, response));
			assertThat(evaluationStarted.await(5, TimeUnit.SECONDS)).isTrue();
			assertThat(evaluationInterrupted.await(10, TimeUnit.SECONDS)).isTrue();
			return future.get(10, TimeUnit.SECONDS);
		} finally {
			executor.shutdownNow();
		}
	}

	private static MockHttpServletRequest newQueryRequest() {
		MockHttpServletRequest request = new MockHttpServletRequest();
		request.setMethod(RequestMethod.POST.name());
		request.setContentType(Protocol.FORM_MIME_TYPE);
		request.setParameter(Protocol.QUERY_PARAM_NAME, QUERY);
		request.addHeader("Accept", "application/sparql-results+json");
		return request;
	}

	private static String readHttpHeaders(InputStream input) throws IOException {
		StringBuilder result = new StringBuilder();
		int previous = -1;
		int current;
		while ((current = input.read()) != -1) {
			result.append((char) current);
			if (previous == '\r' && current == '\n' && result.length() >= 4
					&& result.substring(result.length() - 4).equals("\r\n\r\n")) {
				return result.toString();
			}
			previous = current;
		}
		return result.toString();
	}

	private static final class ExchangeResponse extends MockHttpServletResponse {
		private final HttpExchange exchange;
		private final ServletOutputStream outputStream = new ServletOutputStream() {
			private OutputStream body;

			@Override
			public void write(int value) throws IOException {
				ensureCommitted();
				body.write(value);
			}

			@Override
			public void flush() throws IOException {
				ensureCommitted();
				body.flush();
			}

			@Override
			public void close() throws IOException {
				ensureCommitted();
				body.close();
			}

			@Override
			public boolean isReady() {
				return true;
			}

			@Override
			public void setWriteListener(WriteListener writeListener) {
				// Synchronous test stream.
			}

			private void ensureCommitted() throws IOException {
				if (body == null) {
					String contentType = ExchangeResponse.this.getContentType();
					if (contentType != null) {
						exchange.getResponseHeaders().set("Content-Type", contentType);
					}
					String contentDisposition = ExchangeResponse.this.getHeader("Content-Disposition");
					if (contentDisposition != null) {
						exchange.getResponseHeaders().set("Content-Disposition", contentDisposition);
					}
					exchange.sendResponseHeaders(ExchangeResponse.this.getStatus(), 0);
					body = exchange.getResponseBody();
				}
			}
		};

		private ExchangeResponse(HttpExchange exchange) {
			this.exchange = exchange;
		}

		@Override
		public ServletOutputStream getOutputStream() {
			return outputStream;
		}
	}

	private static final class DisconnectingResponse extends MockHttpServletResponse {
		private final ServletOutputStream outputStream = new ServletOutputStream() {
			@Override
			public void write(int value) throws IOException {
				throw new IOException("client disconnected");
			}

			@Override
			public boolean isReady() {
				return true;
			}

			@Override
			public void setWriteListener(WriteListener writeListener) {
				// Synchronous test stream.
			}
		};

		@Override
		public ServletOutputStream getOutputStream() {
			return outputStream;
		}
	}
